def border(g):
    h,w=len(g),len(g[0]); c=Counter()
    for j in range(w): c[g[0][j]]+=1; c[g[-1][j]]+=1
    for i in range(1,h-1): c[g[i][0]]+=1; c[g[i][-1]]+=1
    return c
